selected.content:
/**
 * 外部结果回调接收（模拟服务 → 中台）：付款、扣款、授信审批。
 * 幂等由各业务服务保证：终态业务单收到重复回调直接确认（DUPLICATE_CALLBACK 不改变状态）。
 * 回调成功只代表外部环节完成；提款是否成功以中台入账状态为准，授信是否生效以中台账本为准。
 */
@RestController
@RequestMapping("/middle/api/v1/callbacks")
public class ExternalResultController {

    private static final Logger log = LoggerFactory.getLogger(ExternalResultController.class);

    private final DrawdownOrderRepository drawdownRepo;
    private final RepaymentOrderRepository repayRepo;
    private final CreditApplicationRepository creditRepo;
    private final DrawdownService drawdownService;
    private final RepaymentService repaymentService;
    private final CreditService creditService;

/**
 * 查单与补偿任务（不引入消息中间件，用定时任务收敛异步结果，见边界设计原则 6）：
 * 1. 提交失败 → 重新提交（模拟服务按 bizOrderNo 幂等）；
 * 2. 受理中超时未收到回调 → 主动查单（"回调未送达，通过查单取得结果"场景）；
 * 3. 提款入账未完成（TO_BOOK / RETRY_NEEDED）→ 重试入账，先查借据是否已 ACTIVE 防重复放款；
 * 4. 授信审批受理超时 → 查审批结论。
 */
@Component
public class CompensationTask {

    private static final Logger log = LoggerFactory.getLogger(CompensationTask.class);

    private final DrawdownOrderRepository drawdownRepo;
    private final RepaymentOrderRepository repayRepo;
    private final CreditApplicationRepository creditRepo;
    private final DrawdownService drawdownService;
    private final RepaymentService repaymentService;
    private final CreditService creditService;
    private final long paymentQueryTimeoutSeconds;
    private final int bookingRetryMax;

/** 查单收敛（补偿任务用）。 */
@Transactional
public void queryAndSettle(RepaymentOrder order) {
    SimulatorClient.ExternalStatus status = simulator.query("DEDUCTION", order.getExtSerialNo());
    if ("SUCCESS".equals(status.status()) || "FAILED".equals(status.status())) {
        onDeductionResult(order, status.status());
    } else if ("RESULT_UNCONFIRMED".equals(status.status())) {
        order.setDeductionStatus(RepaymentOrder.DeductionStatus.RESULT_UNCONFIRMED);
    }
}

/**
 * 外部交易流水：付款（PAYMENT）与扣款（DEDUCTION）。
 * 状态：PROCESSING → SUCCESS | FAILED。回调未送达时中台查单也能取到真实终态（query 永远返回真实状态）。
 * 场景配置挂在 bizOrderNo 上，不混入正式业务字段（边界设计 §7）。
 */
@Entity
@Table(name = "ext_transaction")
public class ExtTransaction {

    public enum Kind { PAYMENT, DEDUCTION, APPROVAL }

    public enum Scenario {
        SYNC_SUCCESS, SYNC_REJECT, ASYNC_SUCCESS_DELAY, ASYNC_FAIL, NO_CALLBACK_NEED_QUERY
    }

    @Id
    private String extSerialNo;
    private Kind kind;
    private String bizOrderNo;
    private BigDecimal amount;
    private String accountName;     // 收款人/付款人
    private String accountNo;
    private String status;          // PROCESSING / SUCCESS / FAILED
    private Scenario scenario;
    private int delaySeconds;
    private LocalDateTime processDueAt;      // 异步结果的产生时间
    private boolean resultResolved;          // 终态是否已产生
    private boolean callbackSuppressed;      // NO_CALLBACK 场景：终态已产生但回调不投递
    private LocalDateTime finishedAt;
    private LocalDateTime createdAt;
    // 审批类交易（APPROVAL）专用：结论与批准额度
    private String resultDetail;    // APPROVED / REJECTED
    private BigDecimal resultAmount; // 批准额度（可能低于申请额度）

/** 提交付款；同步终态就地结算，受理中等待回调或查单。 */
public void submitPayment(DrawdownOrder order) {
    try {
        SimulatorClient.PaymentSubmission sub = simulator.submitPayment(
                order.getBizOrderNo(), order.getPayeeName(), order.getPayeeAccount(), order.getAmount());
        order.setExtSerialNo(sub.extSerialNo());
        order.setUpdatedAt(Ids.now());
        switch (sub.status()) {
            case "SUCCESS" -> onPaymentResult(order, "SUCCESS");
            case "REJECTED" -> onPaymentResult(order, "FAILED");
            default -> order.setPaymentStatus(DrawdownOrder.PaymentStatus.PROCESSING);
        }
    } catch (Exception e) {
        // 提交失败保留 TO_SUBMIT，由补偿任务重试（模拟服务按 bizOrderNo 幂等）
        log.warn("付款提交失败，等待补偿重试: {} {}", order.getBizOrderNo(), e.getMessage());
    }
}

/** 查单：模拟服务返回外部交易真实终态（回调未送达时也查得到）。 */
@SuppressWarnings("unchecked")
public ExternalStatus query(String kind, String extSerialNo) {
    String path = "PAYMENT".equals(kind) ? "/sim/api/v1/payments/" : "DEDUCTION".equals(kind) ? "/sim/api/v1/deductions/" : "/sim/api/v1/approvals/";
    try {
        return http.get().uri(path + extSerialNo).retrieve().body(ExternalStatus.class);
    } catch (Exception e) {
        throw new BizException(BizException.Code.SIMULATOR_ERROR);
    }
}

/** 回调投递记录：每次投递的成败都落库，支撑"回调未送达，通过查单取得结果"场景的调查。 */
@Entity
@Table(name = "callback_log")
public class CallbackLog {

    @Id
    private String logId;
    private String extSerialNo;
    private int attempt;
    private boolean success;
    private String response;
    private LocalDateTime deliveredAt;

@Scheduled(fixedDelayString = "${compensation.poll-interval-ms:15000}")
public void compensate() {
    // 提款：提交失败重试
    drawdownRepo.findByPaymentStatus(DrawdownOrder.PaymentStatus.TO_SUBMIT)
            .forEach(drawdownService::submitPayment);
    // 提款：受理超时主动查单
    LocalDateTime deadline = LocalDateTime.now().minus(Duration.ofSeconds(paymentQueryTimeoutSeconds));
    List<DrawdownOrder> pendingPayments = drawdownRepo.findByPaymentStatus(DrawdownOrder.PaymentStatus.PROCESSING);
    for (DrawdownOrder order : pendingPayments) {
        if (order.getUpdatedAt() != null && order.getUpdatedAt().isBefore(deadline)) {
            log.info("提款付款超时，主动查单: {}", order.getBizOrderNo());
            drawdownService.queryAndSettle(order);
        }
    }
    // 提款：入账未完成 → 重试（含"外部已成功、中台未入账"的可恢复状态）
    for (DrawdownOrder order : drawdownRepo.findByBookingStatus(DrawdownOrder.BookingStatus.TO_BOOK)) {
        drawdownService.book(order);
    }
    for (DrawdownOrder order : drawdownRepo.findByBookingStatus(DrawdownOrder.BookingStatus.RETRY_NEEDED)) {
        if (order.getBookingRetryCount() != null && order.getBookingRetryCount() < bookingRetryMax) {
            drawdownService.book(order);
        }
    }
    // 还款：同样的三条补偿线
    repayRepo.findByDeductionStatus(RepaymentOrder.DeductionStatus.TO_SUBMIT)
            .forEach(repaymentService::submitDeduction);
    for (RepaymentOrder order : repayRepo.findByDeductionStatus(RepaymentOrder.DeductionStatus.PROCESSING)) {
        if (order.getUpdatedAt() != null && order.getUpdatedAt().isBefore(deadline)) {
            log.info("还款扣款超时，主动查单: {}", order.getBizOrderNo());
            repaymentService.queryAndSettle(order);
        }
    }
    // 扣款成功但入账未完成的还款订单（PROCESSING 且扣款已 SUCCESS）
    repayRepo.findByDeductionStatus(RepaymentOrder.DeductionStatus.SUCCESS).stream()
            .filter(order -> order.getStatus() == RepaymentOrder.Status.PROCESSING)
            .forEach(repaymentService::book);
    // 授信审批：未拿到流水号的重试提交；受理超时的查审批结论
    creditRepo.findByStatus(CreditApplicationOrder.Status.PROCESSING).forEach(order -> {
        if (order.getApprovalExtSerialNo() == null) {
            creditService.submitApproval(order);
        } else if (order.getUpdatedAt() != null && order.getUpdatedAt().isBefore(deadline)) {
            log.info("授信审批超时，主动查单: {}", order.getBizOrderNo());
            creditService.queryAndSettle(order);
        }
    });
}

