  const cashierId = route.parent.paramMap.get('id');
  const tellerId = route.parent.parent.paramMap.get('id');
  return this.organizationService.getCashierTransactionTemplate(tellerId, cashierId);
}

/**
 * 查单与补偿任务（不引入消息中间件，用定时任务收敛异步结果，见边界设计原则 6）：
 * 1. 提交失败 → 重新提交（模拟服务按 bizOrderNo 幂等）；
 * 2. 受理中超时未收到回调 → 主动查单（"回调未送达，通过查单取得结果"场景）；
 * 3. 提款入账未完成（TO_BOOK / RETRY_NEEDED）→ 重试入账，先查借据是否已 ACTIVE 防重复放款；
 * 4. 授信审批受理超时 → 查审批结论。
 */
@Component
public class CompensationTask {

    private static final Logger log = LoggerFactory.getLogger(CompensationTask.class);

    private final DrawdownOrderRepository drawdownRepo;
    private final RepaymentOrderRepository repayRepo;
    private final CreditApplicationRepository creditRepo;
    private final DrawdownService drawdownService;
    private final RepaymentService repaymentService;
    private final CreditService creditService;
    private final long paymentQueryTimeoutSeconds;
    private final int bookingRetryMax;

/**
 * 授信申请与调整编排：申请单 → 模拟审批（回调/查单）→ 中台生效。
 * 审批结果只是数据；额度生效、降额后保留占用、冻结状态全部由中台账本决定（边界设计 §6 判例）。
 * 冻结/解冻是运营操作，不走审批。
 */
@Service
public class CreditService {

    private static final Logger log = LoggerFactory.getLogger(CreditService.class);

    private final CreditApplicationRepository applicationRepo;
    private final CreditLimitRepository limitRepo;
    private final LimitService limitService;
    private final ProductSubLimitRepository subLimitRepo;
    private final GroupMemberRepository groupMemberRepo;
    private final GuaranteeCoverageRepository coverageRepo;
    private final SimulatorClient simulator;
    private final ObjectMapper objectMapper;

public enum Code {
    QUOTE_EXPIRED("报价已过期，请重新试算"),
    AMOUNT_CHANGED_NEED_REQUOTE("报价条件已变化，需重新确认报价"),
    LIMIT_INSUFFICIENT("可用额度不足"),
    TERM_NOT_SUPPORTED("该产品不支持所选期限"),
    PRODUCT_NOT_OPEN("产品未开放"),
    DUPLICATE_CALLBACK("重复回调已幂等确认"),
    BOOKING_RETRY_EXHAUSTED("入账重试次数已用尽，需人工处理"),
    LOAN_NOT_FOUND("借据不存在"),
    SIMULATOR_ERROR("外部服务不可用");

    public final String message;

    Code(String message) {
        this.message = message;
    }
}

/** 还款订单：扣款执行与入账状态。分配明细来自 Fineract 还款交易（本金/利息/费用），中台保存分配结果用于额度恢复与核对。 */
@Entity
@Table(name = "repayment_order")
public class RepaymentOrder {

    public enum Status { PROCESSING, SUCCESS, FAILED }

    public enum Type { DUE, EARLY_PRINCIPAL, EARLY_SETTLE }

    public enum DeductionStatus { TO_SUBMIT, PROCESSING, SUCCESS, FAILED, RESULT_UNCONFIRMED }

    @Id
    private String bizOrderNo;
    private String loanAccountNo;
    private String creditId;            // 借据所属授信（来自提款业务单关联）
    private String payerAccount;
    private Type type;
    private BigDecimal amount;

    private Status status;
    private DeductionStatus deductionStatus;
    private String extSerialNo;
    private String fineractTransactionId;
    private BigDecimal principalPortion;   // 分配明细：本金部分（恢复额度依据）
    private BigDecimal interestPortion;
    private BigDecimal feePortion;
    private LocalDateTime createdAt;
    private LocalDateTime updatedAt;

/**
 * 付款结果落业务单。幂等：业务单已终态、或该结果已生效时，直接确认不产生任何新记录。
 */
@Transactional
public void onPaymentResult(DrawdownOrder order, String result) {
    if (order.terminal()) {
        return; // 幂等：终态后收到的任何结果只影响外部流水，不改业务单
    }
    order.setUpdatedAt(Ids.now());
    if ("SUCCESS".equals(result)) {
        if (order.getPaymentStatus() == DrawdownOrder.PaymentStatus.SUCCESS) {
            return; // 幂等：成功已受理过
        }
        order.setPaymentStatus(DrawdownOrder.PaymentStatus.SUCCESS);
        order.setStatus(DrawdownOrder.Status.EXTERNAL_SUCCESS_BOOKING_PENDING);
        order.setBookingStatus(DrawdownOrder.BookingStatus.TO_BOOK);
        book(order); // 同步尝试入账；失败转 RETRY_NEEDED 由补偿任务继续
    } else {
        if (order.getPaymentStatus() == DrawdownOrder.PaymentStatus.FAILED) {
            return;
        }
        order.setPaymentStatus(DrawdownOrder.PaymentStatus.FAILED);
        order.setStatus(DrawdownOrder.Status.FAILED);
        limitService.releasePreOccupied(order.getCreditId(), order.getBizOrderNo(), order.getProductId(),
                requiresGuarantee(order.getProductId()), order.getAmount());
    }
}

